# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _load() -> SemanticModelDefinition:
    return SemanticModelDefinition(**TMDLPartsLoader(TMDL_FILES).load())


def _roundtrip() -> tuple[SemanticModelDefinition, SemanticModelDefinition]:
    sm = _load()
    written = TMDLPartsWriter().write(sm)
    sm2 = SemanticModelDefinition(**TMDLPartsLoader(written).load())
    return sm, sm2


# ---------------------------------------------------------------------------
# Parse tests
# ---------------------------------------------------------------------------


def test_parse_succeeds():
    assert _load() is not None


def test_compatibility_level():
    assert _load().compatibilityLevel == 1550


def test_table_count():
    assert len(_load().model.tables) == 18


# ---------------------------------------------------------------------------
# Roundtrip tests
# ---------------------------------------------------------------------------


def test_roundtrip_table_count():
    sm1, sm2 = _roundtrip()
    assert len(sm1.model.tables) == len(sm2.model.tables)


def test_roundtrip_all_table_names_preserved():
    sm1, sm2 = _roundtrip()
    assert {t.name for t in sm1.model.tables} == {t.name for t in sm2.model.tables}


def test_roundtrip_relationship_count():
    sm1, sm2 = _roundtrip()
    assert len(sm1.model.relationships or []) == len(sm2.model.relationships or [])


def test_roundtrip_expression_count():
    sm1, sm2 = _roundtrip()
    assert len(sm1.model.expressions or []) == len(sm2.model.expressions or [])


def test_roundtrip_culture_count():
    sm1, sm2 = _roundtrip()
    assert len(sm1.model.cultures or []) == len(sm2.model.cultures or [])


def test_roundtrip_column_counts_per_table():
    sm1, sm2 = _roundtrip()
    counts1 = {t.name: len(t.columns or []) for t in sm1.model.tables}
    counts2 = {t.name: len(t.columns or []) for t in sm2.model.tables}
    assert counts1 == counts2


def test_roundtrip_measure_counts_per_table():
    sm1, sm2 = _roundtrip()
    counts1 = {t.name: len(t.measures or []) for t in sm1.model.tables}
    counts2 = {t.name: len(t.measures or []) for t in sm2.model.tables}
    assert counts1 == counts2


def test_roundtrip_partition_counts_per_table():
    sm1, sm2 = _roundtrip()
    counts1 = {t.name: len(t.partitions or []) for t in sm1.model.tables}
    counts2 = {t.name: len(t.partitions or []) for t in sm2.model.tables}
    assert counts1 == counts2
